 WHEN (tags ~ '蛋糕|糕饼|西饼|烘焙|甜品|中餐厅|西餐厅|快餐厅|小吃店|面馆|粉面店|火锅店|烧烤店|奶茶店|咖啡厅|茶馆|洗浴|足疗|足道|足浴|按摩|推拿|养生馆|美容院|美发店|理发店|药店|药房|生鲜超市|生鲜店|生鲜市场|农贸市场|菜市场|水果店|蔬菜店|酒店|宾馆|民宿|仓库|物流|餐饮|住宿|医疗|公司企业|交通设施|科教文化|商务住宅' OR c ~ '(^|[|;,])(?!06[0-9]{4}([|;,]|$)|070000([|;,]|$))[0-9]{6}([|;,]|$)') AND NOT (business_snack AND (((pt LIKE '%' || '餐饮服务;餐饮相关场所;餐饮相关' || '%' AND NOT EXISTS (SELECT 1 FROM unnest(string_to_array(pt,'|')) item WHERE item<>'餐饮服务;餐饮相关场所;餐饮相关' AND item !~ '^购物服务;(购物相关场所;购物相关场所|专卖店;专营店|便民商店/便利店;便民商店/便利店|超级市场;(超市|综合超市))$')) AND tags !~ '中餐厅|西餐厅|快餐厅|小吃店|面馆|粉面店|火锅店|烧烤店|奶茶店|咖啡厅|茶馆|洗浴|足疗|足道|足浴|按摩|推拿|养生馆|美容院|美发店|理发店|药店|药房|生鲜超市|生鲜店|生鲜市场|农贸市场|菜市场|水果店|蔬菜店|酒店|宾馆|民宿|仓库|物流' AND tags !~ '蛋糕|糕饼|西饼|烘焙|甜品') OR (tags ~ '蛋糕|糕饼|西饼|烘焙|甜品' AND business_tags !~ '蛋糕|糕饼|西饼|烘焙|甜品' AND tags !~ '中餐厅|西餐厅|快餐厅|小吃店|面馆|粉面店|火锅店|烧烤店|奶茶店|咖啡厅|茶馆|洗浴|足疗|足道|足浴|按摩|推拿|养生馆|美容院|美发店|理发店|药店|药房|生鲜超市|生鲜店|生鲜市场|农贸市场|菜市场|水果店|蔬菜店|酒店|宾馆|民宿|仓库|物流' AND pt LIKE '%糕饼店%' AND NOT EXISTS (SELECT 1 FROM unnest(string_to_array(pt,'|')) item WHERE item NOT LIKE '%糕饼店%' AND item !~ '^购物服务;(购物相关场所;购物相关场所|专卖店;专营店|便民商店/便利店;便民商店/便利店|超级市场;(超市|综合超市))$')))) THEN '高德分类或标签证据冲突，待核验'
 WHEN NOT retail THEN '缺少零食／超市／购物分类或标签证据，待核验'
 WHEN manual='accept' THEN '按 POI ID 人工核实纳入，覆盖自动名称／分类／标签疑点' ELSE '品牌名称与零食／超市／购物证据通过初筛，未验证品牌归属' END FROM flags
$$;
CREATE OR REPLACE FUNCTION brand_policy_decision(brand text, name text, poi_id text, manual text, poi_type text, codes text, raw jsonb) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
 SELECT CASE brand_policy_reason(brand,name,poi_id,manual,poi_type,codes,raw)
 WHEN '品牌名称与零食／超市／购物证据通过初筛，未验证品牌归属' THEN '接受' WHEN '按 POI ID 人工核实纳入，覆盖自动名称／分类／标签疑点' THEN '接受' WHEN '按当前门店记录人工核实纳入（无高德 POI ID），覆盖自动名称／分类／标签疑点' THEN '接受' WHEN '规范连锁门店名称通过初筛；高德分类或标签未证实，尚未核验品牌归属及营业状态' THEN '接受' WHEN '品牌主体明确，购物／餐饮／便利店等相关证据通过初筛，未验证品牌归属' THEN '接受' WHEN '优味多标准分店名称按用户规则优先接受；标签已放宽，未验证品牌归属' THEN '接受' WHEN '好特卖 HotMaxx 完整品牌主体和规范分店或商场地标有购物证据，服装子类不阻断初筛；未验证具体门店归属' THEN '接受' WHEN '好特卖折扣仓超市／临期超市完整名称、购物06编码与超市标签通过初筛；未验证具体门店归属' THEN '接受'
 WHEN '按 POI ID 人工排除' THEN '排除' WHEN '按当前门店记录人工排除（无高德 POI ID）' THEN '排除' WHEN '标注暂停营业、装修中或未开业，非当前营业门店' THEN '排除' WHEN '名称明确为仓库，非营业门店' THEN '排除' WHEN '名称主体明确为餐饮、足浴、生鲜、仓库等非目标业态' THEN '排除' WHEN '相似名称，不按目标品牌收录' THEN '排除' WHEN '高德具体分类或标签明确为棋牌、垂钓、面馆、足浴或生鲜等非目标业态' THEN '排除' WHEN '分类或标签明确为蛋糕／烘焙等非目标业态' THEN '排除' WHEN '高德具体分类或标签明确为餐饮、足浴、生鲜等非目标业态' THEN '排除' WHEN '好想来副食／副食品、奶站或官方名称按用户要求排除' THEN '排除' WHEN '分类或标签为公司、培训机构、农副产品、住宅区、化妆品、日杂店或住宿服务，按用户规则排除' THEN '排除' WHEN '名称主体没有目标品牌依据；其他品牌、普通店名或仅地标命中，不按该品牌收录' THEN '排除' WHEN '名称主体为用户确认的非目标连锁名称' THEN '排除' WHEN '名称以其他店名或业态开头，零食优选仅为后缀描述，不按目标连锁收录' THEN '排除' WHEN '名称明确为分公司、工厂或公司主体，非营业门店' THEN '排除' WHEN '好特卖 HotMaxx 分店括号为纯异业店型，按名称直接排除' THEN '排除'
 ELSE '待核实' END
$$;

UPDATE brand_stores SET raw_json=raw_json WHERE brand_name IN ('好特卖','零食优选','加一加','同喜铺子');
UPDATE brand_dashboard_snapshots AS d SET invalidated_at=NOW()
WHERE EXISTS (SELECT 1 FROM brand_stores AS s WHERE s.tenant_id=d.tenant_id
 AND s.brand_name IN ('好特卖','零食优选','加一加','同喜铺子'));
UPDATE brand_region_cache AS c SET store_count=(
 SELECT count(*) FROM brand_stores AS s WHERE s.tenant_id=c.tenant_id
 AND s.brand_name=c.brand_name AND s.province=c.province AND s.city=c.city
 AND s.library_visible AND s.deleted_at IS NULL)
WHERE c.brand_name IN ('好特卖','零食优选','加一加','同喜铺子');
ANALYZE brand_stores;
COMMIT;
